def _ok(id, result):
    return {"jsonrpc": "2.0", "id": id, "result": result}


def _err(id, code, message):
    return {"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}}


def handle(message, tools):
    if "id" not in message:
        return None
    id = message["id"]
    if message.get("jsonrpc") != "2.0" or not isinstance(message.get("method"), str):
        return _err(id, -32600, "Invalid Request")
    method = message["method"]
    params = message.get("params") or {}
    if method == "tools/list":
        listed = [{"name": n, "description": t["description"], "inputSchema": t["inputSchema"]} for n, t in tools.items()]
        return _ok(id, {"tools": listed})
    if method == "tools/call":
        name = params.get("name")
        if name not in tools:
            return _err(id, -32602, "Unknown tool: " + str(name))
        try:
            text = tools[name]["handler"](params.get("arguments") or {})
        except ValueError as exc:
            return _ok(id, {"content": [{"type": "text", "text": str(exc)}], "isError": True})
        return _ok(id, {"content": [{"type": "text", "text": text}], "isError": False})
    return _err(id, -32601, "Method not found")
